	gfiedler.ndarray( 3, null, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gfiedler.ndarray( 3, undefined, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gfiedler.ndarray( 3, {}, 1, 0, out, 3, 1, 0 ); // $ExpectError
