// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	gfiedler.ndarray(); // $ExpectError
	gfiedler.ndarray( 3 ); // $ExpectError
	gfiedler.ndarray( 3, x ); // $ExpectError
	gfiedler.ndarray( 3, x, 1 ); // $ExpectError
	gfiedler.ndarray( 3, x, 1, 0 ); // $ExpectError
	gfiedler.ndarray( 3, x, 1, 0, out ); // $ExpectError
	gfiedler.ndarray( 3, x, 1, 0, out, 3 ); // $ExpectError
	gfiedler.ndarray( 3, x, 1, 0, out, 3, 1 ); // $ExpectError
	gfiedler.ndarray( 3, x, 1, 0, out, 3, 1, 0, 10 ); // $ExpectError
}
